/**
 * Expense type classification for the expense ledger.
 *
 * - `Salaries` rows are auto-generated by the carryover settlement flow
 *   (carryover -> expense conversion); they are never manually creatable.
 * - `Marketing`, `Logistics`, and `Technology` are operational expense
 *   categories entered manually by accounting staff.
 */
export enum ExpenseType {
  SALARIES = "Salaries",
  MARKETING = "Marketing",
  LOGISTICS = "Logistics",
  TECHNOLOGY = "Technology",
}
